from __future__ import absolute_import
from taf.selenium.gnb.oam.coam.vdu import pages
from taf.selenium.gnb.oam.coam.vdu.pages import v22R2


class Configuration(v22R2.Configuration):
    def __init__(self, driver, version):
        if not self._instance_dict:
            super(Configuration, self).__init__(driver, version)
            self._instance_dict.update({"Compare Objects": CompareObjectsPageV25R1(driver, version)})


class CompareObjectsPageV25R1(pages.CompareObjectsPage):
    MENU_ROUTE_LIST = ['settings', 'Configuration Management', 'Compare Objects']
